package local.tvmorph.tv;
import android.app.*;import android.app.role.RoleManager;import android.content.*;import android.os.*;import android.provider.Settings;
final class StartupSettings {
 private static String t(Context c,String ar,String en){return UiSettings.text(c,ar,en);}
 private static String bootText(Context c,String en,String ar,String fr,String zh,String ja){String l=UiSettings.language(c);return l.equals("ar")?ar:l.equals("fr")?fr:l.equals("zh")?zh:l.equals("ja")?ja:en;}
 static void showBoot(Activity a){
  boolean enabled=UiSettings.prefs(a).getBoolean("launchAtBoot",false),allowed=Settings.canDrawOverlays(a);
  String on=bootText(a,"On","مفعّل","Activé","开启","オン"),off=bootText(a,"Off","متوقف","Désactivé","关闭","オフ");
  String[] options={bootText(a,"Launch when TV starts · ","التشغيل عند بدء التلفزيون · ","Lancer au démarrage · ","电视启动时打开 · ","テレビ起動時に開く · ")+(enabled?on:off),bootText(a,"Background launch permission · ","إذن الفتح من الخلفية · ","Autorisation de lancement · ","后台启动权限 · ","バックグラウンド起動権限 · ")+(allowed?on:off),bootText(a,"How it works","طريقة التشغيل","Fonctionnement","使用说明","使い方")};
  new LauncherDialog.Builder(a).setTitle(bootText(a,"Launch when TV starts","التشغيل عند بدء التلفزيون","Lancer au démarrage","电视启动时打开","テレビ起動時に開く")).setItems(options,(d,w)->{
   if(w==0){UiSettings.prefs(a).edit().putBoolean("launchAtBoot",!enabled).apply();showBoot(a);}else if(w==1)bootPermission(a);else bootHelp(a);
  }).setNegativeButton(bootText(a,"Back","رجوع","Retour","返回","戻る"),null).show();
 }
 private static String bootHelpText(Activity a){return bootText(a,
  "1. Turn on Launch when TV starts.\n2. If startup is blocked, open Background launch permission and manually allow Display over other apps for Morph TV.\n3. Restart the TV fully to test.\n\nYour current launcher stays selected. Morph TV does not draw an overlay. This option runs after a full system boot, not every wake from standby. Some Fire TV/Android TV firmware blocks startup or hides this permission. It cannot be guaranteed on every device. After Force stop, open Morph TV once again.",
  "١. فعّل التشغيل عند بدء التلفزيون.\n٢. لو الفتح ممنوع، افتح إذن الفتح من الخلفية واسمح يدويًا بالظهور فوق التطبيقات لـ Morph TV.\n٣. أعد تشغيل التلفزيون بالكامل للتجربة.\n\nاللانشر الحالي يفضل كما هو. التطبيق لا يرسم نافذة فوق التطبيقات. الخيار يعمل بعد إقلاع النظام بالكامل، وليس كل رجوع من السكون. بعض إصدارات Fire TV وAndroid TV تمنع الفتح أو تخفي الإذن؛ لا يمكن ضمانه على كل جهاز. بعد فرض الإيقاف، افتح Morph TV مرة أخرى.",
  "1. Activez le lancement au démarrage.\n2. Si nécessaire, autorisez manuellement Afficher par-dessus les autres applications pour Morph TV.\n3. Redémarrez complètement le téléviseur.\n\nLe lanceur actuel reste sélectionné. Morph TV ne dessine aucune superposition. Cette option concerne le démarrage complet, pas chaque sortie de veille. Certains appareils Fire TV/Android TV bloquent ce lancement ou masquent l’autorisation. Après un arrêt forcé, ouvrez Morph TV une fois.",
  "1. 开启电视启动时打开。\n2. 如启动被阻止，请在后台启动权限中手动允许 Morph TV 显示在其他应用上层。\n3. 完全重启电视以测试。\n\n不会更改当前桌面，也不会绘制悬浮窗。此选项仅适用于系统完整启动，不适用于每次待机唤醒。部分 Fire TV/Android TV 固件可能阻止启动或隐藏权限，无法保证所有设备均可用。强行停止后需重新打开一次应用。",
  "1. テレビ起動時に開くをオンにします。\n2. 必要なら起動権限から Morph TV の他のアプリの上に重ねて表示を手動で許可します。\n3. テレビを完全に再起動して確認します。\n\n現在のホームアプリは変更されず、オーバーレイも描画しません。完全なシステム起動が対象で、待機からの復帰ごとではありません。一部の Fire TV/Android TV では起動が制限され、権限画面がない場合もあります。強制停止後は一度アプリを開いてください。");}
 static void bootHelp(Activity a){new LauncherDialog.Builder(a).setMessage(bootHelpText(a)).setPositiveButton("OK",(d,w)->showBoot(a)).show();}
 static void bootPermission(Activity a){
  new LauncherDialog.Builder(a).setTitle(bootText(a,"Optional startup permission","إذن اختياري للتشغيل","Autorisation facultative","可选启动权限","任意の起動権限")).setMessage(bootHelpText(a)).setPositiveButton(bootText(a,"Open system settings","فتح إعدادات النظام","Ouvrir les paramètres","打开系统设置","システム設定を開く"),(d,w)->{
   try{a.startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,android.net.Uri.parse("package:"+a.getPackageName())));}catch(RuntimeException e){new LauncherDialog.Builder(a).setMessage(bootText(a,"This TV does not expose this permission page. Startup may be restricted by its firmware.","التلفزيون لا يعرض صفحة الإذن دي. النظام ممكن يمنع التشغيل التلقائي.","Ce téléviseur ne propose pas cette page. Le démarrage peut être limité par son système.","电视未提供此权限页面，系统可能限制自动启动。","このテレビには権限画面がありません。自動起動が制限される場合があります。")).setPositiveButton("OK",null).show();}
  }).setNegativeButton(bootText(a,"Cancel","إلغاء","Annuler","取消","キャンセル"),null).show();
 }
 static void showReturn(Activity a){
  boolean enabled=UiSettings.prefs(a).getBoolean("returnExternal",false);
  String text=t(a,"اختياري: اضغط رجوع مرتين بسرعة للعودة إلى Morph TV من تطبيق أو مصدر فتحته منه. ضغطة واحدة تفضل للتنقل العادي. الخدمة تتابع اسم التطبيق وتستقبل أحداث الأزرار؛ تستخدم زر الرجوع فقط ولا تقرأ محتوى الشاشة أو الكتابة.\n\nبعد التفعيل، اسمح بخدمة Morph TV · Home navigation في تسهيلات الاستخدام. لو كانت مفعلة بالفعل، اقفلها وافتحها مرة ثانية للسماح بوظيفة الأزرار. بعض الأجهزة قد تمنع استقبال الأزرار.","Optional: press Back twice quickly to return to Morph TV from an app or input opened here. A single Back keeps normal navigation. The service observes the app package and receives key events; it uses only Back, without reading screen contents or typed text.\n\nEnable Morph TV · Home navigation in Accessibility. If already enabled, turn it off and on again to allow key filtering. Some devices may block key events.");
  new LauncherDialog.Builder(a).setTitle(t(a,"رجوع سريع إلى Morph TV","Quick return to Morph TV")).setMessage(text).setPositiveButton(enabled?t(a,"إيقاف","Turn off"):t(a,"تفعيل وفتح الإذن","Enable and open permission"),(d,w)->{UiSettings.prefs(a).edit().putBoolean("returnExternal",!enabled).apply();HomeOverrideService.refresh();if(!enabled)try{a.startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}catch(ActivityNotFoundException e){new LauncherDialog.Builder(a).setMessage(t(a,"افتح إعدادات التلفزيون ← تسهيلات الاستخدام وفعّل خدمة Morph TV يدويًا.","Open TV Settings → Accessibility and enable Morph TV manually.")).setPositiveButton("OK",null).show();}}).setNegativeButton(t(a,"رجوع","Back"),null).show();
 }
 static void show(Activity a){
  HomeOverrideService.refresh();ComponentName home=HomeOverrideService.home(a);boolean own=home!=null&&home.getPackageName().equals(a.getPackageName()),granted=HomeOverrideService.granted(a),override=UiSettings.prefs(a).getBoolean("overrideHome",false),boot=UiSettings.prefs(a).getBoolean("launchAtBoot",false);
  String homeName=own?"Morph TV":home==null?t(a,"لم يتم تحديدها","Not selected"):home.getPackageName();if(home!=null&&!own)try{homeName=String.valueOf(a.getPackageManager().getApplicationLabel(a.getPackageManager().getApplicationInfo(home.getPackageName(),0)));}catch(Exception ignored){}
  String[] options={t(a,"اختيار واجهة Home · ","Choose Home app · ")+homeName,t(a,"تجاوز الواجهة الأصلية · ","Override current launcher · ")+(override&&granted?t(a,"مفعّل","On"):override?t(a,"يحتاج إذن تسهيلات الاستخدام","Needs accessibility permission"):t(a,"متوقف","Off")),t(a,"التشغيل عند بدء التلفزيون · ","Launch when TV starts · ")+(boot?t(a,"مفعّلة","On"):t(a,"متوقفة","Off")),t(a,"إذن تسهيلات الاستخدام · ","Accessibility permission · ")+(granted?t(a,"مفعّل","On"):t(a,"غير مفعّل","Off")),bootText(a,"Android settings tools →","أدوات إعدادات أندرويد →","Outils de réglages Android →","Android 设置工具 →","Android 設定ツール →")};
  new LauncherDialog.Builder(a).setTitle(t(a,"واجهة التلفزيون والتشغيل التلقائي","TV home & startup")).setItems(options,(d,w)->{if(w==0)chooseHome(a);else if(w==1){if(override){UiSettings.prefs(a).edit().putBoolean("overrideHome",false).apply();show(a);}else disclosure(a,true);}else if(w==2){showBoot(a);}else if(w==4)SystemSettingsTools.show(a);else disclosure(a,false);}).setNegativeButton(t(a,"رجوع","Back"),null).show();
 }
 static void chooseHome(Activity a){if(Build.VERSION.SDK_INT>=29)try{RoleManager role=(RoleManager)a.getSystemService(Activity.ROLE_SERVICE);if(role!=null&&role.isRoleAvailable(RoleManager.ROLE_HOME)){a.startActivityForResult(role.createRequestRoleIntent(RoleManager.ROLE_HOME),4701);return;}}catch(RuntimeException ignored){}try{a.startActivity(new Intent(Settings.ACTION_HOME_SETTINGS));}catch(ActivityNotFoundException e){new LauncherDialog.Builder(a).setMessage(t(a,"النظام لا يتيح اختيار Home هنا. جرّب تجاوز الواجهة الأصلية بإذن تسهيلات الاستخدام.","This firmware does not expose the Home picker. Try the optional accessibility launcher override.")).setPositiveButton("OK",null).show();}}
 static void disclosure(Activity a,boolean enable){String message=t(a,"الخدمة اختيارية. تراقب اسم حزمة ونافذة واجهة Home فقط، وتفتح Morph TV عند ظهورها. لا تقرأ محتوى الشاشة أو الكتابة ولا تتحكم في التطبيقات الأخرى. فعّل Morph TV · Home navigation يدويًا في صفحة تسهيلات الاستخدام. يمكن إيقاف الخدمة من نفس الصفحة. توافق التشغيل بعد السكون والإقلاع يعتمد على النظام.","Optional service: observes the Home window package/activity name and opens Morph TV when that Home activity appears. It does not read screen contents or typed text, or control other apps. Manually enable Morph TV · Home navigation in Accessibility settings. Disable it on the same page anytime. Wake/boot behavior depends on the firmware.");if(HomeOverrideService.projectivyEnabled(a))message+="\n\n"+t(a,"خدمة Projectivy مفعّلة. أوقف Override current launcher داخل Projectivy قبل تشغيل التجاوز هنا حتى لا يتعارض الاثنان.","Projectivy accessibility is enabled. Turn off Override current launcher inside Projectivy before enabling Morph TV override, to avoid competing launchers.");
  new LauncherDialog.Builder(a).setTitle(t(a,"تفعيل التنقل إلى Morph TV","Enable Morph TV Home navigation")).setMessage(message).setPositiveButton(t(a,"متابعة إلى تسهيلات الاستخدام","Continue to Accessibility"),(d,w)->{if(enable)UiSettings.prefs(a).edit().putBoolean("overrideHome",true).apply();HomeOverrideService.refresh();try{a.startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}catch(ActivityNotFoundException e){new LauncherDialog.Builder(a).setMessage(t(a,"هذا النظام لا يعرض إعدادات الخدمة. لا يمكن تفعيل الإذن تلقائيًا. افتح إعدادات التلفزيون ← تسهيلات الاستخدام إن كانت متاحة.","This firmware does not expose this settings page. Permission cannot be enabled automatically. Open TV Settings → Accessibility if available.")).setPositiveButton("OK",null).show();}}).setNegativeButton(t(a,"إلغاء","Cancel"),null).show();
 }
}
